  "implementation": "def solve(case):
    # Validate input structure
    if not isinstance(case, dict):
        raise ValueError('case must be a dict')
    if 'threshold' not in case:
        raise ValueError('missing threshold')
    threshold = case['threshold']
    if not isinstance(threshold, (int, float)):
        raise ValueError('threshold must be numeric')
    if 'calls' not in case or not isinstance(case['calls'], list):
        raise ValueError('missing or invalid calls')
    calls = case['calls']

    accepted_ids = []
    diagnostics = []

    for call in calls:
        # Validate each call
        if not isinstance(call, dict):
            raise ValueError('each call must be a dict')
        required = ['call_id', 'loss_without_call', 'loss_with_call', 'prediction_tokens', 'parseable']
        for key in required:
            if key not in call:
                raise ValueError(f'missing key {key} in call')
        call_id = call['call_id']
        loss_without = call['loss_without_call']
        loss_with = call['loss_with_call']
        tokens = call['prediction_tokens']
        parseable = call['parseable']

        if not isinstance(call_id, str):
            raise ValueError('call_id must be a string')
        if not isinstance(loss_without, (int, float)):
            raise ValueError('loss_without_call must be numeric')
        if not isinstance(loss_with, (int, float)):
            raise ValueError('loss_with_call must be numeric')
        if not isinstance(tokens, int):
            raise ValueError('prediction_tokens must be integer')
        if tokens <= 0:
            raise ValueError('prediction_tokens must be positive')
        if not isinstance(parseable, bool):
            raise ValueError('parseable must be boolean')

        gain = loss_without - loss_with
        normalized_gain = gain / tokens
        # Round to 6 decimal places
        normalized_gain_rounded = round(normalized_gain, 6)

        accepted = parseable and normalized_gain_rounded >= threshold

        diagnostics.append({
            'accepted': accepted,
            'call_id': call_id,
            'normalized_gain': normalized_gain_rounded
        })
        if accepted:
            accepted_ids.append(call_id)

    return {
        'accepted_call_ids': accepted_ids,
        'diagnostics': diagnostics
    }"
}
